// src/planning/diagram.ts
function safeId(raw, index) {
  const cleaned = raw.replace(/[^A-Za-z0-9_]/g, "_");
  return /^[A-Za-z_]/.test(cleaned) ? cleaned : `n${index}_${cleaned}`;
}
function safeLabel(raw) {
  return raw.replace(/["`]/g, "'").replace(/[\n\r]+/g, " ").trim().slice(0, 80) || "(unnamed)";
}
function shape(type, id, label) {
  const l = `"${label}"`;
  switch (type) {
    case "trigger":
      return `${id}([${l}])`;
    case "agent":
      return `${id}(${l})`;
    case "human":
      return `${id}[/${l}/]`;
    case "condition":
      return `${id}{${l}}`;
    case "done":
      return `${id}((${l}))`;
    case "script":
      return `${id}[${l}]`;
  }
}
var CLASSDEFS = [
  "classDef trigger fill:#eef2ff,stroke:#8891c7,color:#1e2a5a;",
  "classDef script fill:#e7f6ec,stroke:#38a24e,color:#14532d;",
  "classDef agent fill:#eef1ff,stroke:#6366f1,color:#312e81;",
  "classDef human fill:#fff7ed,stroke:#f59e0b,color:#7c2d12;",
  "classDef condition fill:#f5f3ff,stroke:#a78bfa,color:#4c1d95;",
  "classDef done fill:#f3f4f6,stroke:#9ca3af,color:#374151;"
];
function toMermaid(plan2) {
  const ids = new Map(plan2.nodes.map((node, index) => [node.id, safeId(node.id, index)]));
  const lines = ["flowchart LR"];
  if (plan2.name) lines.push(`  %% ${safeLabel(plan2.name)}`);
  for (const node of plan2.nodes) {
    lines.push(`  ${shape(node.type, ids.get(node.id), safeLabel(node.label))}:::${node.type}`);
  }
  for (const edge of plan2.edges) {
    const label = edge.label ? `|"${safeLabel(edge.label)}"|` : "";
    lines.push(`  ${ids.get(edge.from)} -->${label} ${ids.get(edge.to)}`);
  }
  lines.push(`  ${CLASSDEFS.join("\n  ")}`);
  return lines.join("\n");
}

