      name: automation.name,
      planPath: automation.planPath,
      runs: runs.length,
      lastStatus: runs[0]?.status ?? null,
      lastAt: runs[0]?.startedAt ?? null,
      tokensSaved: totalSavings(runs).totalTokensSaved
